#!/usr/bin/env python3
"""Draws the flat SVG illustrations in public/img/verbs (original artwork for this project).
Run once: python3 scripts/draw-verb-icons.py"""
from pathlib import Path

OUT = Path(__file__).resolve().parent.parent / 'public' / 'img' / 'verbs'
OUT.mkdir(parents=True, exist_ok=True)

BG = lambda c='#cfe8ff': f'<rect width="64" height="64" rx="8" fill="{c}"/>'
GROUND = lambda c='#9aa5b1', y=46: f'<rect x="0" y="{y}" width="64" height="{64 - y}" fill="{c}"/>'
PERSON = lambda x, y, shirt='#e63946', skin='#f5c6a5', hair='#5a2d1a': (
    f'<circle cx="{x}" cy="{y}" r="5" fill="{skin}"/><path d="M{x - 5} {y - 1} A5 5 0 0 1 {x + 5} {y - 1}Z" fill="{hair}"/>'
    f'<rect x="{x - 5}" y="{y + 5}" width="10" height="13" rx="3" fill="{shirt}"/>'
    f'<rect x="{x - 4}" y="{y + 18}" width="3" height="9" fill="#2b3a67"/><rect x="{x + 1}" y="{y + 18}" width="3" height="9" fill="#2b3a67"/>')
ARM = lambda x1, y1, x2, y2, skin='#f5c6a5': f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{skin}" stroke-width="3" stroke-linecap="round"/>'
NOTE = lambda x, y, c='#333': f'<circle cx="{x}" cy="{y}" r="2.5" fill="{c}"/><rect x="{x + 1.5}" y="{y - 9}" width="1.5" height="9" fill="{c}"/><path d="M{x + 3} {y - 9} q4 1 4 4" stroke="{c}" stroke-width="1.5" fill="none"/>'

ICONS = {
    'arrive-at-the-airport': BG() + GROUND('#c8ccd2') + '<path d="M6 30 L30 22 L34 12 L38 12 L37 22 L56 26 L56 30 L37 30 L36 40 L32 40 L30 30Z" fill="#fff" stroke="#7c8a99"/>' + PERSON(14, 26, '#e63946') + '<rect x="20" y="38" width="8" height="10" rx="1" fill="#8d5524"/><circle cx="22" cy="49" r="1.5" fill="#222"/><circle cx="26" cy="49" r="1.5" fill="#222"/>',
    'call-my-mother': BG('#fce4ec') + PERSON(24, 20, '#4d96ff') + '<rect x="30" y="16" width="6" height="12" rx="2" fill="#333"/><rect x="31" y="18" width="4" height="7" fill="#8ecae6"/>' + ARM(29, 27, 32, 22) + '<path d="M40 14 Q50 10 52 20" stroke="#e63946" stroke-width="2" fill="none" stroke-dasharray="3 2"/><circle cx="52" cy="26" r="4" fill="#f5c6a5"/><path d="M48 25 A4 4 0 0 1 56 25Z" fill="#888"/><path d="M50 24 L52 22 L54 24 L52 27Z" fill="#e63946" transform="translate(0,-8)"/>',
    'take-care-of-my-daughter': BG('#fff3e0') + GROUND('#a8b5a0') + PERSON(24, 14, '#9c27b0') + '<circle cx="42" cy="30" r="4" fill="#f5c6a5"/><path d="M38 29 A4 4 0 0 1 46 29Z" fill="#e0a040"/><rect x="38" y="34" width="8" height="10" rx="2" fill="#ffd54a"/><rect x="39" y="44" width="2.5" height="6" fill="#2b3a67"/><rect x="42.5" y="44" width="2.5" height="6" fill="#2b3a67"/>' + ARM(29, 22, 38, 34) + '<path d="M50 10 l2 -3 l2 3 -2 3z" fill="#e63946"/>',
    'cook-fish': BG('#fff8e1') + '<rect x="8" y="38" width="48" height="10" rx="3" fill="#333"/><rect x="12" y="34" width="40" height="6" rx="2" fill="#555"/><rect x="54" y="40" width="8" height="4" rx="1" fill="#333"/><ellipse cx="32" cy="34" rx="12" ry="4" fill="#f4a261"/><path d="M44 34 L50 30 L50 38Z" fill="#f4a261"/><circle cx="24" cy="33" r="1" fill="#222"/><path d="M20 26 q2 -4 0 -8 M32 24 q2 -4 0 -8 M44 26 q2 -4 0 -8" stroke="#bbb" stroke-width="1.5" fill="none"/>' + PERSON(14, 16, '#fff', hair='#222') + '<rect x="9" y="6" width="10" height="5" rx="2" fill="#fff"/>',
    'dance-salsa': BG('#311b92') + '<circle cx="14" cy="10" r="3" fill="#ffd54a"/><circle cx="50" cy="8" r="2" fill="#e63946"/><circle cx="56" cy="20" r="2" fill="#4caf50"/>' + PERSON(24, 20, '#e63946') + PERSON(40, 20, '#4d96ff') + ARM(29, 28, 35, 28) + ARM(19, 27, 12, 20) + ARM(45, 27, 52, 20) + NOTE(8, 40, '#ffd54a') + NOTE(54, 44, '#ffd54a'),
    'drive-a-car': BG() + GROUND('#4a4e57', 44) + '<rect x="8" y="30" width="48" height="14" rx="3" fill="#e63946"/><rect x="16" y="18" width="30" height="14" rx="3" fill="#e63946"/><rect x="19" y="20" width="24" height="10" fill="#bde0fe"/><circle cx="27" cy="26" r="3.5" fill="#f5c6a5"/><path d="M23.5 25 A3.5 3.5 0 0 1 30.5 25Z" fill="#5a2d1a"/><circle cx="18" cy="46" r="5" fill="#222"/><circle cx="46" cy="46" r="5" fill="#222"/><circle cx="14" cy="36" r="2" fill="#fff59d"/>',
    'give-a-gift': BG('#fce4ec') + PERSON(18, 18, '#4d96ff') + PERSON(48, 18, '#4caf50') + ARM(23, 26, 30, 30) + ARM(43, 26, 38, 30) + '<rect x="27" y="30" width="12" height="10" fill="#e63946"/><rect x="27" y="33" width="12" height="2" fill="#ffd54a"/><rect x="32" y="30" width="2" height="10" fill="#ffd54a"/><path d="M30 30 q3 -5 3 0 q0 -5 3 0" stroke="#ffd54a" stroke-width="1.5" fill="none"/>',
    'help-my-grandmother': BG('#e8f5e9') + GROUND('#a8b5a0') + PERSON(24, 14, '#4d96ff') + PERSON(42, 16, '#9c27b0', hair='#ddd') + ARM(29, 22, 37, 24) + '<line x1="50" y1="26" x2="52" y2="46" stroke="#8d5524" stroke-width="2.5" stroke-linecap="round"/><rect x="20" y="36" width="12" height="8" fill="#8d5524"/><rect x="20" y="34" width="12" height="3" fill="#a8d5a8"/>',
    'meet-friends': BG('#fff8e1') + PERSON(14, 18, '#e63946') + PERSON(32, 16, '#4d96ff') + PERSON(50, 18, '#4caf50') + ARM(19, 26, 27, 26) + ARM(37, 26, 45, 26) + '<text x="32" y="10" font-family="sans-serif" font-size="8" font-weight="bold" fill="#333" text-anchor="middle">Hi!</text>',
    'play-soccer': BG() + GROUND('#7cb342', 40) + '<rect x="42" y="10" width="16" height="30" fill="none" stroke="#fff" stroke-width="2"/>' + ''.join(f'<line x1="{44 + i * 4}" y1="12" x2="{44 + i * 4}" y2="40" stroke="#fff" stroke-width=".7"/>' for i in range(4)) + PERSON(18, 14, '#ffd54a') + '<line x1="21" y1="32" x2="30" y2="40" stroke="#2b3a67" stroke-width="3" stroke-linecap="round"/><circle cx="34" cy="42" r="5" fill="#fff" stroke="#222" stroke-width="1.5"/><path d="M31 40 L34 39 L37 40 L36 44 L32 44Z" fill="#222"/>',
    'play-the-piano': BG('#efebe9') + '<rect x="6" y="26" width="52" height="22" rx="2" fill="#222"/><rect x="8" y="34" width="48" height="12" fill="#fff"/>' + ''.join(f'<rect x="{9 + i * 6}" y="34" width="5" height="12" fill="#fff" stroke="#999" stroke-width=".5"/>' for i in range(8)) + ''.join(f'<rect x="{13 + i * 6}" y="34" width="3" height="7" fill="#222"/>' for i in range(7)) + PERSON(32, 12, '#1d3557') + ARM(27, 20, 22, 34) + ARM(37, 20, 42, 34) + NOTE(54, 14) + NOTE(10, 18),
    'sing': BG('#fce4ec') + PERSON(30, 18, '#9c27b0') + '<rect x="34" y="20" width="4" height="12" rx="2" fill="#333"/><circle cx="36" cy="20" r="4" fill="#555"/>' + ARM(35, 26, 36, 24) + NOTE(50, 16, '#e63946') + NOTE(54, 30, '#4d96ff') + NOTE(12, 22, '#4caf50') + '<ellipse cx="30" cy="20" rx="1.5" ry="2" fill="#222"/>',
    'speak-italian': BG('#e8f5e9') + PERSON(20, 24, '#4caf50') + '<rect x="30" y="8" width="30" height="16" rx="6" fill="#fff" stroke="#333"/><path d="M34 24 L32 30 L40 24Z" fill="#fff" stroke="#333"/><text x="45" y="19" font-family="sans-serif" font-size="6" font-weight="bold" fill="#009246" text-anchor="middle">BUON</text><rect x="44" y="30" width="4" height="8" fill="#009246"/><rect x="48" y="30" width="4" height="8" fill="#fff"/><rect x="52" y="30" width="4" height="8" fill="#ce2b37"/>',
    'swim-in-the-ocean': BG('#e3f2fd') + '<rect x="0" y="30" width="64" height="34" fill="#4d96ff"/><path d="M0 30 q8 -4 16 0 t16 0 t16 0 t16 0" stroke="#fff" stroke-width="2" fill="none"/><path d="M0 44 q8 -4 16 0 t16 0 t16 0 t16 0" stroke="#8ecae6" stroke-width="2" fill="none"/><circle cx="26" cy="26" r="5" fill="#f5c6a5"/><path d="M21 25 A5 5 0 0 1 31 25Z" fill="#e63946"/><rect x="30" y="26" width="16" height="6" rx="3" fill="#f5c6a5"/>' + ARM(46, 28, 52, 20) + '<circle cx="54" cy="8" r="5" fill="#ffd54a"/>',
    'travel-by-bus': BG() + GROUND('#4a4e57', 46) + '<rect x="6" y="14" width="52" height="32" rx="4" fill="#4d96ff"/><rect x="10" y="18" width="44" height="12" fill="#bde0fe"/>' + ''.join(f'<circle cx="{16 + i * 12}" cy="24" r="3" fill="#f5c6a5"/>' for i in range(4)) + '<rect x="10" y="34" width="44" height="6" fill="#1d3557"/><text x="32" y="39" font-family="sans-serif" font-size="5" font-weight="bold" fill="#fff" text-anchor="middle">TRAVEL</text><circle cx="16" cy="48" r="5" fill="#222"/><circle cx="48" cy="48" r="5" fill="#222"/>',
}

for name, body in ICONS.items():
    svg = f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64">{body}</svg>'
    (OUT / f'{name}.svg').write_text(svg)
print(f'wrote {len(ICONS)} icons to {OUT}')
